from pathlib import Path
from PIL import Image
import json,hashlib,shutil,copy,sys
ROOT=Path(__file__).resolve().parent;V2=ROOT.parents[2]
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def write(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def relative(p):return str(p.relative_to(V2)).replace('\\','/')
def import_helper(sid,folder):
 gen=read(ROOT/'generation.json');base=V2/'support'/folder;support=read(base/'records'/(sid+'.json'));r=next(r for r in gen['records'] if r['id']==sid)
 assert not r.get('sha256'),'No second actual call/import for existing source'
 raw=base/support['raw'];original=Path(support.get('actualOriginalPath',support.get('original','')))
 assert sha(raw)==sha(original),'Exact original output required'
 pp=base/support['prompt'];target=ROOT/'prompts'/'history'/(sid+'-actual-helper-prompt.txt');target.parent.mkdir(exist_ok=True);shutil.copy2(pp,target)
 r['preparedPrompt']={'file':r['prompt'],'sha256':r['promptSha256']};r['prompt']=relative(target);r['promptSha256']=sha(target)
 inputs=[]
 for i,q in enumerate(support['inputs']):
  p=base/q['file'];assert sha(p)==q['sha256'];dst=ROOT/'inputs'/'helper'/sid/(str(i+1)+'.png');dst.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dst);inputs.append(q|{'file':relative(dst)})
 r['inputs']=inputs;r['original']=str(original);r['originalSha256']=sha(original);r['sha256']=sha(raw);dst=V2/r['raw'];dst.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(raw,dst);im=Image.open(dst);r['sourceSize']=list(im.size);r['mode']=im.mode;r['tool']='built-in-imagegen';r['transparentRequested']=True;r['sourceViewed']=False;r['rawImmutable']=True;r['status']='imported-helper-raw-awaiting-source-review';r['outputProvenance']={'originalToolOutput':str(original),'workspaceRaw':str(dst.resolve()),'copiedOriginalUnchanged':True,'helperRecord':relative(base/'records'/(sid+'.json')),'helperRecordSha256':sha(base/'records'/(sid+'.json'))};r['selected']=False
 write(ROOT/'sources'/(sid+'.receipt.json'),r);gen['actualCoverage']['generatedSources']=sum(bool(r.get('sha256')) for r in gen['records']);write(ROOT/'generation.json',gen);print(sid,'imported exact helper raw/prompt/input snapshots')
def actual_prompt(sid,mode):
 gen=read(ROOT/'generation.json');r=next(r for r in gen['records'] if r['id']==sid);p=V2/r['prompt'];txt=p.read_text(encoding='utf-8');actual=txt.strip() if mode=='trim' else txt+'\n';q=ROOT/'prompts'/'history'/(sid+'-actual-tool-prompt.txt');q.parent.mkdir(exist_ok=True);q.write_text(actual,encoding='utf-8');r['preparedPrompt']={'file':r['prompt'],'sha256':r['promptSha256']};r['prompt']=relative(q);r['promptSha256']=sha(q);r['literalToolPromptNormalization']=mode;write(ROOT/'generation.json',gen);write(ROOT/'sources'/(sid+'.receipt.json'),r)
